
.card {
  background: var(--grad-card);
  border-radius: 20px;
  padding: 20px;
  border: 1px solid var(--c-card-border);
  box-shadow: var(--c-card-shadow);
}

.char-card {
  text-align: center;
  padding: 24px 16px;
}

.avatar {
  width: 110px;
  height: 110px;
  margin: 0 auto 12px;
  background: linear-gradient(135deg, #2d3561, #1e1e3f);
  border-radius: 50%;
  border: 3px solid #667eea;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 52px;
}

.char-name {
  display: inline-block;
  font-size: 18px;
  font-weight: 700;
  color: var(--c-text-bright);
  min-width: 80px;
}

.char-class {
  font-size: 13px;
  color: var(--c-accent);
  margin-top: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.text-sm {
  min-width: 60px;
}

.tags {
  display: flex;
  gap: 6px;
  justify-content: center;
  margin-top: 10px;
  flex-wrap: wrap;
}

.tag {
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 500;
  border: 1px solid;
}

.exp-section {
  margin-top: 16px;
}

.exp-label {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--c-text-dim);
  margin-bottom: 4px;
}

.exp-fill {
  background: var(--grad-primary);
}

.exp-hint {
  font-size: 11px;
  color: #ffd54f;
  margin-top: 4px;
  text-align: right;
}

.stat-track {
  flex: 1;
  height: 10px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 5px;
  overflow: hidden;
}

.stat-fill {
  height: 100%;
  border-radius: 5px;
  transition: width 0.5s ease;
}

:deep(.num-sm) {
  width: 30px;
}
:deep(.num-md) {
  width: 50px;
}
